scwin.isValidDate = function (psDate) {
    let [y, m, d] = psDate.split(/[-.]/);

    if (y.length == 8) {
        d = y.substr(6, 2);
        m = y.substr(4, 2);
        y = y.substr(0, 4);
    }
    else if (y.length > 4 && typeof m !== "undefined" && typeof d === "undefined") {
        d = m;
        m = y.substr(4);
        y = y.substr(0, 4);
    }

    if (typeof y === "undefined" || typeof m === "undefined" || typeof d === "undefined") {
        return false;
    }

    if (m.startsWith("0")) {
        m = m.substr(1);
    }
    if (d.startsWith("0")) {
        d = d.substr(1);
    }

    if (!(/^\d{4}$/).test(y) || !(/^(0{0,1}[1-9]|1[0-2])$/).test(m) || !(/^(0{0,1}[1-9]|[12][0-9]|3[01])$/).test(d)) {
        return false;
    }

    if (m == 2) {
        if (d > (new Date(y, m)).getUTCDate()) {
            return false;
        }
    }

    return true;
}
 */

